/**
 * interviewee-profile.ts — 角色画像
 *
 * 为诊断 Phase 0 提供结构化角色定义：
 *   - 职责范围 → 确定哪些缝隙维度与该角色相关
 *   - 决策权等级 → 影响置信度权重
 *   - 信息需求 → 确定需要采集的数据类型
 *   - 沟通偏好 → 定制访谈方式和报告格式
 *
 * 角色画像在 Phase 0 用于：
 *   1. 生成针对性问卷
 *   2. 确定证据置信度权重
 *   3. 选择报告呈现方式
 */
/** 角色类型（扩展现有角色分类） */
export type IntervieweeRoleType = 'founder' | 'executive' | 'engineering-manager' | 'product-manager' | 'senior-engineer' | 'junior-engineer' | 'designer' | 'data-scientist' | 'devops' | 'hr' | 'operations' | 'sales' | 'marketing';
/** 决策权等级 */
export type DecisionAuthority = 'strategic' | 'tactical' | 'operational' | 'none';
/** 沟通偏好 */
export interface CommunicationPreference {
    /** 正式度 0-1 */
    formality: number;
    /** 细节度 0-1 */
    detailLevel: number;
    /** 数据驱动 vs 直觉驱动 0-1（0=纯直觉，1=纯数据） */
    dataDriven: number;
    /** 团队导向 vs 个人导向 0-1（0=纯个人，1=纯团队） */
    teamOriented: number;
}
/** 角色画像 */
export interface IntervieweeProfile {
    roleType: IntervieweeRoleType;
    /** 自定义角色名称（如 "技术 VP"） */
    customTitle?: string;
    /** 职责范围 */
    responsibilities: string[];
    /** 决策权等级 */
    decisionAuthority: DecisionAuthority;
    /** 关心的缝隙维度（按优先级排序） */
    concernedDimensions: string[];
    /** 可提供的证据类型 */
    evidenceSources: ('interview' | 'observation' | 'document' | 'metrics' | 'log')[];
    /** 沟通偏好 */
    communication: CommunicationPreference;
    /** 在诊断中的置信度权重 0-1 */
    evidenceWeight: number;
}
/** 角色画像构建参数（Phase 0 输入） */
export interface ProfileBuildInput {
    roleType: IntervieweeRoleType;
    customTitle?: string;
    /** 覆盖默认维度优先级 */
    overrideDimensions?: string[];
    /** 覆盖默认证据权重 */
    overrideWeight?: number;
}
/** 根据输入构建角色画像 */
export declare function buildIntervieweeProfile(input: ProfileBuildInput): IntervieweeProfile;
/** 获取内置角色类型列表 */
export declare function listRoleTypes(): IntervieweeRoleType[];
/** 根据职责关键词推荐角色类型 */
export declare function suggestRoleType(responsibilities: string[]): IntervieweeRoleType[];
/** 为角色生成推荐的诊断维度优先级 */
export declare function getDimensionPriority(profile: IntervieweeProfile, allDimensions: string[]): string[];
/** 多角色聚合：计算团队级别的维度优先级 */
export declare function aggregateTeamPriorities(profiles: IntervieweeProfile[], allDimensions: string[]): Map<string, number>;
